from pathlib import Path
from pynwb import NWBHDF5IO
p=next(Path('/app/data').glob('sub-*/*.nwb'))
with NWBHDF5IO(str(p),'r',load_namespaces=True) as io:
 n=io.read()
 for k,v in n.acquisition.items():
  print(k,type(v).__name__)
  if hasattr(v,'time_series'):
   for x,y in v.time_series.items(): print(' ',x,type(y).__name__,'data',y.data.shape,y.data.dtype,'timestamps',None if y.timestamps is None else y.timestamps.shape,'rate',y.rate,'unit',y.unit,'desc',y.description[:300])
 u=n.units
 for col in ['classification','anno_name','unit_quality']:
  vals=u[col][:]
  import numpy as np
  z,c=np.unique(vals.astype(str),return_counts=True)
  print(col,list(zip(z.tolist(),c.tolist()))[:50])
 print('electrode columns',n.electrodes.colnames)
 print(n.electrodes[['location','x','y','z']][:].head(20).to_string())
