const r = await tools.exec_command({"cmd":"python3 - <<'PY'
from pathlib import Path
from collections import Counter
from pynwb import NWBHDF5IO
import numpy as np,json,time
files=sorted(Path('/app/data').glob('sub-*/*.nwb')); coarse=Counter(); ann=Counter(); zero=[]; go_bad=[]; window_bad=[]; details=[]
for i,p in enumerate(files):
 with NWBHDF5IO(str(p),'r',load_namespaces=True) as io:
  n=io.read(); cls=np.asarray(n.units['classification'][:]).astype(str); good=np.flatnonzero(cls=='good'); ng=len(good)
  if ng==0: zero.append(p.name)
  anns=np.asarray(n.units['anno_name'][:]).astype(str)[good]; ann.update(anns.tolist())
  groups=n.units['electrode_group'][:]
  for j in good:
   try: br=json.loads(groups[j].location).get('brain_regions','unknown')
   except Exception: br='unknown'
   coarse[br]+=1
  tr=n.trials[:]; go=np.asarray(n.acquisition['BehavioralEvents'].time_series['go_start_times'].timestamps[:]);
  if len(go)!=len(tr): go_bad.append((p.name,len(tr),len(go)))
  else:
   valid=(go-2.5>=tr.start_time.to_numpy()-1e-8)&(go+1.5<=tr.stop_time.to_numpy()+1e-8)
   if not valid.all(): window_bad.append((p.name,int((~valid).sum())))
  details.append((p.name,len(tr),ng))
 if (i+1)%40==0: print('progress',i+1,flush=True)
print('ZERO',zero)
print('COARSE_GOOD',dict(coarse))
print('ANN_UNIQUE',len(ann),'EMPTY_GOOD',ann[''],'TOP',ann.most_common(30))
